@startuml

class Customer {
  + name : string
  + dateOfBirth : date
  + address : string
  + taxCode : string
}

class Broker {
  + brokerId : int
  + name : string
  + contactInfo : string
}

class Contract {
  + contractId : int
  + signingDate : date
  + insuredAmount : float
  + coverageDetails : string
}

class Policy {
  + policyId : int
  + policyType : string
  + description : string
}

class Claim {
  + claimId : int
  + claimDate : date
  + status : string
}

class Estimator {
  + estimatorId : int
  + name : string
  + expertiseArea : string
}

class CompensationDecision {
  + decisionId : int
  + approvalDate : date
  + eligibleCosts : float
}

Customer "1" -- "1..*" Broker
Broker "1" -- "0..*" Contract
Contract "1" -- "1" Policy
Customer "1" -- "0..*" Claim
Claim "0..*" -- "1..*" Estimator
Estimator "1" -- "0..*" CompensationDecision

@enduml

